def merge_dicts_by_key(main_data, secondary_data, key):
    try:
        secondary_dict = {d[key]: d for d in secondary_data}
        result = []

        for item in main_data:
            secondary_item = secondary_dict.get(item.get(key))
            if secondary_item is None:
