function searchAndCount(arr, target) {
  // Check if the array is sorted
  let isSorted = true;
  for (let i = 1; i < arr.length; i++) {
    if (arr[i] < arr[i - 1]) {
      isSorted = false;
      break;
    }
  }

  // If the array is not sorted, sort it
  if (!isSorted) {
    arr.sort((a, b) => a - b);
  }

  // Perform binary search to find the target element
  let left = 0;
  let right = arr.length - 1;
  let found = false;
  let count = 0;

  while (left <= right) {
    let mid = Math.floor((left + right) / 2);
    if (arr[mid] === target) {
      found = true;
      count++;
      // Check for duplicates on the left side
      let i = mid - 1;
      while (i >= 0 && arr[i] === target) {
        count++;
        i--;
      }
      // Check for duplicates on the right side
      let j = mid + 1;
      while (j < arr.length && arr[j] === target) {
        count++;
        j++;
      }
      break;
    } else if (arr[mid] < target) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  if (found) {
    return count;
  } else {
    return -1;
  }
}

