public static int hoursInMonth(int month, int year) {
    // First, we need to determine the number of days in the given month
    int days;

    // Using a switch statement to determine days based on month
    switch (month) {
        case 1: case 3: case 5: case 7: case 8: case 10: case 12:
            days = 31;
            break;
        case 4: case 6: case 9: case 11:
            days = 30;
            break;
        case 2:
            // For February, we need to check if it's a leap year
            if (isLeapYear(year)) {
                days = 29;
            } else {
                days = 28;
            }
            break;
        default:
            // This should not happen due to precondition, but handling it anyway
            return -1;
    }

    // Convert days to hours (24 hours per day)
    return days * 24;
}

// Since the problem mentions using isLeapYear method, 
