Below is a sample Python code that uses the Boto3 library to manage Amazon S3 services using multi-threading. 

This code includes functions for uploading, downloading, listing all objects resiliently in a bucket, deleting objects and paginated object listing in a bucket.

Before running the script, please make sure to configure your AWS credentials either by setting your environment variables or by using `aws configure`.

```python
import boto3
import concurrent.futures

s3 = boto3.resource('s3')

def upload_file(bucket_name, file_name):
    try:
        s3.meta.client.upload_file(file_name, bucket_name, file_name)
        print(f"File {file_name} uploaded successfully.")
    except Exception as e:
        print(f"Error occurred while uploading file {file_name}. Error: {str(e)}")

def download_file(bucket_name, file_name):
    try:
        s3.meta.client.download_file(bucket_name, file_name, file_name)
        print(f"File {file_name} downloaded successfully.")
    except Exception as e:
        print(f"Error occurred while downloading file {file_name}. Error: {str(e)}")

def list_objects(bucket_name):
    try:
        for obj in s3.Bucket(bucket_name).objects.all():
            print(f"- {obj.key}")
    except Exception as e:
        print(f"Error occurred while listing objects. Error: {str(e)}")

    return

def delete_file(bucket_name, file_name):
    try:
        s3.Object(bucket_name, file_name).delete()
        print(f"File {file_name} deleted successfully.")
    except Exception as e:
        print(f"Error occurred while deleting file {file_name}. Error: {str(e)}")

def list_objects_paginated(bucket_name, max_keys):
    paginator = s3.meta.client.get_paginator('list_objects')
    for result in paginator.paginate(Bucket=bucket_name, PaginationConfig={'MaxItems': max_keys}):
        for file in result.get('Contents', []):
            print(f"- {file['Key']}")

    return

# Program Execution Starts here
def manage_s3_service(bucket_name, operation, file_name=None, max_keys=None):
    with concurrent.futures.ThreadPoolExecutor(max_workers=5) as executor:
        if operation == 'upload':
            executor.submit(upload_file, bucket_name, file_name)
        elif operation == 'download':
            executor.submit(download_file, bucket_name, file_name)
        elif operation == 'list':
            executor.submit(list_objects, bucket_name)
        elif operation == 'delete':
            executor.submit(delete_file, bucket_name, file_name)
        elif operation == 'paginate':
            executor.submit(list_objects_paginated, bucket_name, max_keys)

manage_s3_service('your_bucket_name', 'list')
```

In this code, replace `'your_bucket_name'` with the name of your S3 bucket and `'operation'` with the operation you want to perform (either 'upload', 'download', 'list', 'delete', 'paginate'). If the operation is 'upload' or 'download' or 'delete', replace `'file_name'` with the name of the file you want to upload/download/delete. If 'operation' is 'paginate', replace `'max_keys'` with the maximum number of items you want to list per page.
Finally, run the function `manage_s3_service()`. 

This script uses a thread pool executor to upload/download/delete/list objects on S3 in parallel using multi-threading. 

Remember to handle AWS credentials properly and install necessary packages (`boto3` in this case) before running this script.

