def calculate_total_spent(orders):
    total_spent = {}
    for order in orders:
        customer = order['customer']
        items = order['items']
        total = sum(item['price'] for item in items)
        if customer in total_spent:
            total_spent[customer] += total
        else:
            total_spent[customer] = total
    return total_spent

